___CSS_LOADER_EXPORT___.push([module.id, `:where(.qg-panel-surface, .qg-graph-node) {
    --qg-panel-background: white;
    --qg-panel-border-color: hsl(0, 0%, 85%);
    --qg-panel-divider-color: hsl(0, 0%, 90%);
    --qg-panel-hover-background: hsl(0, 0%, 94%);
    --qg-panel-border-radius: 0.5em;
    --qg-panel-inner-radius: calc(var(--qg-panel-border-radius) - 1px);
    --qg-panel-shadow:
        0 2px 6px hsl(0, 0%, 0%, 0.08),
        0 1px 2px hsl(0, 0%, 0%, 0.06);
}

.qg-panel-surface {
    box-sizing: border-box;
    border: 1px solid var(--qg-panel-border-color);
    border-radius: var(--qg-panel-border-radius);
    background-color: var(--qg-panel-background);
    box-shadow: var(--qg-panel-shadow);
}

@media (forced-colors: active) {
    .qg-panel-surface {
        border-color: CanvasText;
    }
}
