___CSS_LOADER_EXPORT___.push([module.id, `.qg-settings-popover {
    --qg-settings-text: hsl(0, 0%, 15%);
    --qg-settings-accent: hsl(210, 75%, 38%);
    --qg-settings-focus: hsl(210, 90%, 55%);

    position: fixed;
    inset: auto auto 15px calc(15px + var(--qg-graph-toolbar-button-size) + 0.5em);
    inline-size: min(22em, calc(100vw - 2em));
    max-block-size: calc(100dvh - 2em);
    margin: 0;
    padding: 0;
    overflow: auto;
    color: var(--qg-settings-text);
}

.qg-settings-body {
    font-size: 0.875em;
    line-height: 1.4;
}

.qg-settings-note {
    margin: -0.2em 0.75em 0.6em;
    color: hsl(0, 0%, 40%);
    font-size: 0.85em;
}

.qg-settings-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.5em 0.75em;
    border-block-end: 1px solid var(--qg-panel-divider-color);

    & h2 {
        margin: 0;
        font: inherit;
        font-weight: 600;
    }
}

.qg-settings-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.75em;
    block-size: 1.75em;
    padding: 0;
    border: 0;
    border-radius: 0.25em;
    color: inherit;
    background: transparent;
    cursor: pointer;

    &:hover {
        background: var(--qg-panel-hover-background);
    }

    & svg {
        inline-size: 1em;
        block-size: 1em;
        fill: none;
        stroke: currentColor;
        stroke-width: 2;
        stroke-linecap: round;
    }
}

.qg-settings-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1em;
    padding: 0.4em 0.75em;

    & select {
        min-inline-size: 9em;
        padding: 0.25em;
        color: inherit;
        background: var(--qg-panel-background);
        border: 1px solid var(--qg-panel-border-color);
        border-radius: 0.25em;
        font: inherit;
    }
}

.qg-settings-footer {
    padding: 0.65em 0.75em;
    border-block-start: 1px solid var(--qg-panel-divider-color);

    & button {
        padding: 0;
        border: 0;
        color: var(--qg-settings-accent);
        background: transparent;
        font: inherit;
        cursor: pointer;
    }
}

.qg-settings-close:focus-visible,
.qg-settings-row select:focus-visible,
.qg-settings-footer button:focus-visible {
    outline: 2px solid var(--qg-settings-focus);
    outline-offset: 2px;
}

.query-graph:has(.qg-settings-popover:popover-open) .qg-settings-button {
    background: var(--qg-panel-hover-background);
}

.query-graph:has(.qg-settings-popover:popover-open) .qg-settings-button ~ .qg-icon-button-tooltip {
    visibility: hidden;
}

@supports (position-area: inline-end) {
    .qg-settings-popover {
        inset: auto;
        margin-inline-start: 0.5em;
        position-area: inline-end span-block-start;
        position-try-fallbacks: flip-inline, flip-block, flip-block flip-inline;
    }
}

@media (max-width: 32em) {
    .qg-settings-popover {
        inset: auto 0 0;
        inline-size: 100%;
        max-block-size: 80dvh;
        margin: 0;
        border-radius: 0.75em 0.75em 0 0;
        position-area: none;
    }

    .qg-settings-row {
        align-items: stretch;
        flex-direction: column;
        gap: 0.35em;
    }
}

@media (forced-colors: active) {
    .qg-settings-header,
    .qg-settings-footer,
    .qg-settings-row select {
        border-color: CanvasText;
    }
}
